  const messages = errors.map(error => {
    if (error.keyword === 'required') {
      const prop = error.params?.missingProperty;
      return `Required property '${prop}' is missing`;
    }
    if (error.keyword !== 'type') {
      const path = error.instancePath || error.dataPath || '<root>';
      return `Validation error at '${path}': ${error.keyword}`;
    }
    const path = (error.instancePath || error.dataPath || '').replace(/^\.$/, '');
    const fieldName = path ? path.replace(/^\./, '').split('.').pop() : '<root>';
    const expectedType = error.params?.type;
    return `Property '${fieldName}' must be of type '${expectedType}'`;
  });
  return messages.join('; ');
}

